check_code:
# symbols with orientation in degrees; alternate: diagonal swap, then rotate every symbol 90 cw in place
f4={'TL':('tri',90),'TR':('arrow',180),'BL':('T',0),'BR':('semi',90)}
f5={p:(s,(a+90)%360) for p,(s,a) in f4.items()}
f3={'TL':('semi',90),'TR':('T',0),'BL':('arrow',180),'BR':('tri',90)}
f2={'TL':('semi',0),'TR':('T',270),'BL':('arrow',90),'BR':('tri',0)}
assert f3=={p:(s,(a+90)%360) for p,(s,a) in f2.items()}
sw={'TL':'BR','BR':'TL','TR':'BL','BL':'TR'}
assert f4=={sw[p]:v for p,v in f3.items()}
opts={'A':{'TL':('semi',180),'TR':('T',90),'BL':('arrow',270),'BR':('tri',180)},
      'B':{'TL':('tri',180),'TR':('arrow',270),'BL':('T',90),'BR':('semi',180)},
      'C':{'TL':('tri',0),'TR':('arrow',270),'BL':('T',180),'BR':('semi',0)},
      'D':{'TL':('tri',0),'TR':('arrow',270),'BL':('T',90),'BR':('semi',0)}}
assert f5==opts['B']
for k in 'ACD': assert f5!=opts[k]
